text:
Here's your water tracker: tap + after each glass, and it fills up to your goal of 8.

```page
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Water tracker</title>
<style>
  body { font-family: system-ui, sans-serif; margin: 0; padding: 24px; background: #eef6fb; color: #123; text-align: center; }
  h1 { font-size: 1.3rem; margin: 0 0 4px; }
  #date { color: #567; font-size: .9rem; margin-bottom: 16px; }
  #count { font-size: 3rem; font-weight: 700; margin: 8px 0; }
  #msg { min-height: 1.4em; margin-bottom: 12px; }
  #glasses { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; max-width: 360px; margin: 0 auto 20px; }
  .g { width: 56px; height: 72px; border: 2px solid #4a9fd4; border-radius: 4px 4px 12px 12px; background: #fff; }
  .g.full { background: linear-gradient(#7cc4ee, #3b8fcb); }
  button { font-size: 1.1rem; padding: 10px 22px; margin: 4px; border: 0; border-radius: 8px; background: #3b8fcb; color: #fff; cursor: pointer; }
  button.alt { background: #9ab; }
</style>
</head>
<body>
  <h1>Daily water intake</h1>
  <div id="date"></div>
  <div id="count"></div>
  <div id="msg"></div>
  <div id="glasses"></div>
  <button id="add">+ 1 glass</button>
  <button id="sub" class="alt">− 1</button>
  <button id="reset" class="alt">Reset</button>
<script>
  var GOAL = 8;
  var today = new Date();
  var key = "water-" + today.getFullYear() + "-" + (today.getMonth() + 1) + "-" + today.getDate();
  var n = 0;
  try { n = parseInt(localStorage.getItem(key), 10) || 0; } catch (e) {}

  function save() { try { localStorage.setItem(key, String(n)); } catch (e) {} }

  function draw() {
    document.getElementById("date").textContent = today.toDateString();
    document.getElementById("count").textContent = n + " / " + GOAL;
    document.getElementById("msg").textContent =
      n >= GOAL ? "Goal reached. Well done!" : (GOAL - n) + " more to go";
    var box = document.getElementById("glasses");
    box.innerHTML = "";
    var total = Math.max(GOAL, n);
    for (var i = 0; i < total; i++) {
      var d = document.createElement("div");
      d.className = "g" + (i < n ? " full" : "");
      box.appendChild(d);
    }
  }

  document.getElementById("add").onclick = function () { n++; save(); draw(); };
  document.getElementById("sub").onclick = function () { if (n > 0) n--; save(); draw(); };
  document.getElementById("reset").onclick = function () { n = 0; save(); draw(); };
  draw();
</script>
</body>
</html>
```

It starts fresh each day. Your count is saved on this device if the app allows it; otherwise it resets when you close the page.
